.\end {align*}

\begin {align*}
 \mathbb {P}(b_t = 0, z_t \mid  z_{t - 1}, s_t) &= (1 - \psi (s_t, z_{t - 1})) \cdot  \delta _{\{z_{t} = z_{t - 1}\}} \\
 \mathbb {P}(b_t = 1, z_t \mid  z_{t - 1}, s_t) &= \psi (s_t, z_{t - 1}) \cdot  \eta (z_t \mid  s_t)
.\end {align*}

